"""Self-check for check_gradle_verification_metadata.py.

The CI run only sees the metadata of the pull request at hand; these cases pin the branches that
must reject (a changed checksum, an <also-trust> slipped into an existing entry, a reordered or
duplicated block, a weakened <configuration>) and the ones that must pass (new versions, dropped
versions, warning mode without --enforce).
"""

import subprocess
import sys
from pathlib import Path

SCRIPT = Path(__file__).resolve().parent / "check_gradle_verification_metadata.py"

A = "a" * 64
B = "b" * 64
C = "c" * 64


CONFIGURATION = """   <configuration>
      <verify-metadata>true</verify-metadata>
      <verify-signatures>false</verify-signatures>
      <trusted-artifacts>
         <trust file=".*-sources[.]jar" regex="true"/>
      </trusted-artifacts>
   </configuration>
"""


def metadata(*components: str, configuration: str = CONFIGURATION) -> str:
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<verification-metadata xmlns="https://schema.gradle.org/dependency-verification">\n'
        + configuration
        + "   <components>\n"
        + "".join(components)
        + "   </components>\n</verification-metadata>\n"
    )


def component(
    version: str, sha: str, also: str | None = None, *, reordered: bool = False
) -> str:
    inner = (
        f'<sha256 value="{sha}" origin="Generated by Gradle"/>'
        if also is None
        else f'<sha256 value="{sha}" origin="Generated by Gradle">\n'
        f'<also-trust value="{also}"/>\n</sha256>'
    )
    attributes = (
        f'version="{version}" name="lib" group="org.example"'
        if reordered
        else f'group="org.example" name="lib" version="{version}"'
    )
    return (
        f"<component {attributes}>\n"
        f'<artifact name="lib-{version}.jar">\n{inner}\n</artifact>\n</component>\n'
    )


def run(tmp_path: Path, base: str, head: str, *flags: str) -> subprocess.CompletedProcess:
    (tmp_path / "base.xml").write_text(base, encoding="utf-8")
    (tmp_path / "head.xml").write_text(head, encoding="utf-8")
    return subprocess.run(
        [
            sys.executable,
            str(SCRIPT),
            str(tmp_path / "base.xml"),
            str(tmp_path / "head.xml"),
            *flags,
        ],
        capture_output=True,
        text=True,
    )


def test_new_and_dropped_versions_pass(tmp_path):
    result = run(
        tmp_path,
        metadata(component("1.0", A), component("1.1", B)),
        metadata(component("1.1", B), component("1.2", C)),
        "--enforce",
    )
    assert result.returncode == 0, result.stdout
    assert "1 artifact file(s) added, 1 removed, 0 with changed checksums" in result.stdout


def test_changed_checksum_fails_when_enforced(tmp_path):
    result = run(
        tmp_path, metadata(component("1.0", A)), metadata(component("1.0", B)), "--enforce"
    )
    assert result.returncode == 1
    assert "::error::org.example:lib:1.0 lib-1.0.jar" in result.stdout


def test_also_trust_added_to_existing_entry_fails_when_enforced(tmp_path):
    result = run(
        tmp_path, metadata(component("1.0", A)), metadata(component("1.0", A, also=B)), "--enforce"
    )
    assert result.returncode == 1
    assert "::error::" in result.stdout


def test_changed_checksum_only_warns_without_enforce(tmp_path):
    result = run(tmp_path, metadata(component("1.0", A)), metadata(component("1.0", B)))
    assert result.returncode == 0
    assert "::warning::org.example:lib:1.0 lib-1.0.jar" in result.stdout


def test_repository_metadata_parses(tmp_path):
    repo_file = SCRIPT.parents[2] / "backend" / "gradle" / "verification-metadata.xml"
    text = repo_file.read_text(encoding="utf-8")
    result = run(tmp_path, metadata(), text)
    assert result.returncode == 0, result.stdout
    assert int(result.stdout.split()[0]) > 1000, result.stdout


def test_reordered_attributes_are_the_same_coordinates(tmp_path):
    result = run(
        tmp_path,
        metadata(component("1.0", A)),
        metadata(component("1.0", B, reordered=True)),
        "--enforce",
    )
    assert result.returncode == 1
    assert "::error::org.example:lib:1.0 lib-1.0.jar" in result.stdout


def test_duplicate_component_fails_even_without_enforce(tmp_path):
    result = run(
        tmp_path,
        metadata(component("1.0", A)),
        metadata(component("1.0", A), component("1.0", B, reordered=True)),
    )
    assert result.returncode == 1
    assert "::error::component org.example:lib:1.0 listed twice" in result.stdout


def test_duplicate_artifact_fails(tmp_path):
    twice = component("1.0", A).replace(
        "</component>",
        f'<artifact name="lib-1.0.jar">\n<sha256 value="{B}" origin="x"/>\n</artifact>\n'
        "</component>",
    )
    result = run(tmp_path, metadata(component("1.0", A)), metadata(twice))
    assert result.returncode == 1
    assert "::error::artifact org.example:lib:1.0 lib-1.0.jar listed twice" in result.stdout


def test_broader_trust_rule_fails_when_enforced(tmp_path):
    weakened = CONFIGURATION.replace(".*-sources[.]jar", ".*")
    result = run(
        tmp_path,
        metadata(component("1.0", A)),
        metadata(component("1.0", A), configuration=weakened),
        "--enforce",
    )
    assert result.returncode == 1
    assert "::error::<configuration> differs" in result.stdout


def test_disabled_verification_only_warns_without_enforce(tmp_path):
    disabled = CONFIGURATION.replace(
        "<verify-metadata>true</verify-metadata>", "<verify-metadata>false</verify-metadata>"
    )
    result = run(
        tmp_path,
        metadata(component("1.0", A)),
        metadata(component("1.0", A), configuration=disabled),
    )
    assert result.returncode == 0
    assert "::warning::<configuration> differs" in result.stdout


def test_reformatted_configuration_is_unchanged(tmp_path):
    reformatted = CONFIGURATION.replace("\n      ", "\n  ").replace(
        'file=".*-sources[.]jar" regex="true"', 'regex="true" file=".*-sources[.]jar"'
    )
    result = run(
        tmp_path,
        metadata(component("1.0", A)),
        metadata(component("1.0", A), configuration=reformatted),
        "--enforce",
    )
    assert result.returncode == 0, result.stdout


def test_swapped_primary_and_also_trust_is_unchanged(tmp_path):
    result = run(
        tmp_path,
        metadata(component("1.0", A, also=B)),
        metadata(component("1.0", B, also=A)),
        "--enforce",
    )
    assert result.returncode == 0, result.stdout
    assert "0 with changed checksums" in result.stdout


def test_details_list_removed_files_and_configuration_diff(tmp_path):
    weakened = CONFIGURATION.replace(".*-sources[.]jar", ".*")
    result = run(
        tmp_path,
        metadata(component("1.0", A), component("1.1", B)),
        metadata(component("1.1", B), configuration=weakened),
        "--details",
    )
    assert result.returncode == 0
    assert "removed: org.example:lib:1.0 lib-1.0.jar" in result.stdout
    lines = [line.replace(" ", "") for line in result.stdout.splitlines()]
    assert '-<trustfile=".*-sources[.]jar"regex="true"/>' in lines
    assert '+<trustfile=".*"regex="true"/>' in lines
